'use strict';

/* ================================================================== *
 * Project Atlas
 *
 * Two data layers, never mixed:
 *   inventory.json — harvested facts, regenerated by scan.js
 *   verdicts.json  — your judgments only, written from this page
 * ================================================================== */

const $ = (sel) => document.querySelector(sel);

const state = {
  inventory: null,
  repos: [],
  verdicts: {},
  selectedKey: null,
  saveTimer: null,
  saving: false,
  sortCol: 'commits',
  sortDir: -1,
  filters: {
    search: '',
    group: 'owner',
    color: 'recency',
    hue: 'red',
    hueTo: 'aqua',
    scale: 'auto',
    size: 'sqrt-effort',
    visibility: 'visible',
  },
  panelPinned: false,
  undrawn: [],
  recencyScale: null,
  /* Focus is additive and by inclusion: you pick the groups you want to see,
   * and everything else steps aside. Empty set = show everything, which is
   * the default and what you get back by clearing.
   * Kept per grouping mode, because "DollhouseMCP" means nothing once you
   * regroup by language. This is view state, not a judgment, so it lives in
   * localStorage and never touches verdicts.json. */
  focus: {},
};

function focusSet() {
  const m = state.filters.group;
  if (!state.focus[m]) state.focus[m] = new Set();
  return state.focus[m];
}

function toggleFocus(name) {
  const s = focusSet();
  if (s.has(name)) s.delete(name); else s.add(name);
  persistFocus();
  closePanel();
  render();
}

function clearFocus() {
  focusSet().clear();
  persistFocus();
  render();
}

function persistFocus() {
  const plain = {};
  for (const [k, v] of Object.entries(state.focus)) if (v.size) plain[k] = [...v];
  localStorage.setItem('atlas-focus', JSON.stringify(plain));
}

function restoreFocus() {
  try {
    const plain = JSON.parse(localStorage.getItem('atlas-focus') || '{}');
    for (const [k, v] of Object.entries(plain)) state.focus[k] = new Set(v);
  } catch { /* nothing saved yet */ }
}

/* -------------------------------------------------------- vocabulary */

/* Status is ORDINAL — "how alive is this" — so it gets one hue stepped by
 * liveness, not five competing hues. Five adjacent categorical hues cannot
 * clear the colour-vision gates on a treemap (every tile touches every other),
 * but a validated ordinal ramp can, and the glyph carries exact identity. */
const STATUSES = [
  { id: 'active', label: 'Active', glyph: '●', step: 6, key: 'a' },
  { id: 'in-use', label: 'In use, not developed', glyph: '▣', step: 5, key: 'u' },
  { id: 'someday', label: 'Someday', glyph: '◔', step: 4, key: 's' },
  { id: 'done', label: 'Done', glyph: '✓', step: 3, key: 'd' },
  { id: 'dead', label: 'Dead', glyph: '✕', step: 2, key: 'x' },
];

/* Provenance IS categorical, and three is the documented ceiling for
 * all-pairs adjacency — which is exactly how many real values there are. */
const PROVENANCE = [
  // Each family drifts toward a neighbour across the ramp so a block of "mine"
  // does not read as one flat wash of blue, while still staying recognisably
  // its own family against the other two.
  { id: 'mine', label: 'Mine', glyph: '◆', hue: 'blue', hueTo: 'violet', varName: '--series-1', ink: '--series-1-ink' },
  { id: 'fork', label: 'Fork of someone else', glyph: '⑂', hue: 'yellow', hueTo: 'orange', varName: '--series-2', ink: '--series-2-ink' },
  { id: 'external', label: "Clone of someone else's", glyph: '↓', hue: 'aqua', hueTo: 'green', varName: '--series-3', ink: '--series-3-ink' },
  { id: 'unknown', label: 'Unknown', glyph: '?', hue: 'grey', hueTo: 'grey', varName: '--neutral', ink: '--neutral-ink' },
];

const ISSUE_BINS = [
  { max: 1, label: 'none' },
  { max: 3, label: '1–2' },
  { max: 6, label: '3–5' },
  { max: 16, label: '6–15' },
  { max: 41, label: '16–40' },
  { max: 101, label: '41–100' },
  { max: Infinity, label: '100 +' },
];

const PRIORITY_LABEL = { 3: 'High', 2: 'Medium', 1: 'Low', 0: 'None' };

/* Hide is "off my screen for now". Ignore is "this is not my project and I do
 * not want it counted". Both must stay reachable — a one-way hide is a trap,
 * because anything you file away becomes invisible to the tool that filed it. */
const VISIBILITY = [
  { id: 'visible', label: 'Showing', glyph: '👁', step: 6, key: null },
  { id: 'hidden', label: 'Hidden', glyph: '◌', step: 3, key: 'h' },
  { id: 'ignored', label: 'Ignored', glyph: '⊘', step: 1, key: 'i' },
];

function visibilityOf(r) {
  return verdict(r.key).visibility || 'visible';
}

const RECENCY_BINS = [
  { max: 7, label: 'past week' },
  { max: 30, label: '1–4 weeks' },
  { max: 90, label: '1–3 months' },
  { max: 180, label: '3–6 months' },
  { max: 365, label: '6–12 months' },
  { max: 730, label: '1–2 years' },
  { max: Infinity, label: '2 years +' },
];

const PRESENCE_LABEL = {
  both: 'Cloned & pushed',
  'local-only': 'Local only — never pushed',
  'remote-only': 'On GitHub — not cloned here',
};

const COMMON_TAGS = [
  'superseded', 'experiment', 'client work', 'archived upstream', 'reference only',
  'needs cleanup', 'no longer runs', 'merged elsewhere', 'personal',
];

/* ------------------------------------------------------------ helpers */

function cssVar(name) {
  return getComputedStyle(document.documentElement).getPropertyValue(name).trim();
}

function themeName() {
  return document.documentElement.dataset.theme === 'dark' ? 'dark' : 'light';
}

/** Steps of the active ramp, index 0 = least/oldest, 6 = most/newest. */
const _rampCache = new Map();
function rampSteps(hue, toHue) {
  const from = hue || state.filters.hue;
  const to = toHue || (hue ? hue : state.filters.hueTo) || from;
  const key = `${from}>${to}|${themeName()}`;
  let r = _rampCache.get(key);
  if (!r) {
    r = window.ATLAS_PALETTE.buildRamp(from, to, themeName());
    _rampCache.set(key, r);
  }
  return r;
}

/** The ramp currently selected in the toolbar, both hues honoured. */
function activeRamp() {
  return rampSteps(state.filters.hue, state.filters.hueTo);
}

/* ---------------------------------------------------------- text fitting *
 * Estimating character widths from a magic constant does not survive real
 * names — "gstack" wrapped while "autoresearch" vanished. So measure the
 * actual string in the actual font and solve for the largest size that
 * fits the actual box. Everything below is measurement, not guesswork.
 * -------------------------------------------------------------------- */

const FONT_STACK = 'system-ui, -apple-system, "Segoe UI", sans-serif';
const _ctx = document.createElement('canvas').getContext('2d');
const _widthCache = new Map();

/** Width of `text` at font-size 1px, for the given weight. Scales linearly. */
function unitWidth(text, weight) {
  const k = `${weight}|${text}`;
  let w = _widthCache.get(k);
  if (w === undefined) {
    _ctx.font = `${weight} 100px ${FONT_STACK}`;
    w = _ctx.measureText(text).width / 100;
    _widthCache.set(k, w);
  }
  return w;
}

/**
 * How many lines the browser will actually use.
 *
 * total-width ÷ box-width is not the answer: the browser breaks at word
 * boundaries first, and repo names are full of hyphens. "elemental-surveys-
 * research" in a 48px box wants five ragged lines where the ratio predicts
 * three. So walk the break opportunities and pack greedily, exactly as the
 * layout engine will.
 */
function wrapLines(text, boxW, size, weight) {
  if (boxW <= 0) return 99;
  // Break AFTER a hyphen, underscore, slash, dot or space — where CSS does.
  const segs = String(text).split(/(?<=[-_./ ])/);
  let lines = 1;
  let cur = 0;
  for (const seg of segs) {
    const segW = unitWidth(seg, weight) * size;
    if (segW > boxW) {
      // Longer than the box on its own: overflow-wrap:anywhere splits it.
      if (cur > 0) { lines++; cur = 0; }
      lines += Math.ceil(segW / boxW) - 1;
      cur = segW % boxW;
    } else if (cur + segW <= boxW) {
      cur += segW;
    } else {
      lines++;
      cur = segW;
    }
  }
  return lines;
}

/**
 * Largest font size in [min,max] at which `text` fits `boxW`×`boxH`.
 * Tiles wrap with overflow-wrap:anywhere, so a line can break at any glyph
 * and the line count is simply total-width / box-width.
 * Returns { size, lines, fits } — fits:false means even `min` overflows,
 * which the caller may still choose to render and clip.
 */
function fitText(text, boxW, boxH, opts = {}) {
  const { min = 4, max = 13, lineH = 1.15, weight = 600, maxLines = 3 } = opts;
  if (!text || boxW <= 0 || boxH <= 0) return { size: min, lines: 1, fits: false };
  const lineCap = Math.max(1, Math.min(maxLines, Math.floor(boxH / (min * lineH))));

  for (let s = max; s >= min; s -= 0.25) {
    const lines = wrapLines(text, boxW, s, weight);
    if (lines <= lineCap && lines * s * lineH <= boxH) {
      return { size: +s.toFixed(2), lines, fits: true };
    }
  }
  return { size: min, lines: wrapLines(text, boxW, min, weight), fits: false };
}

const _inkCache = new Map();
/** Pick black or white ink by whichever has more contrast on this fill. */
function inkOn(hex) {
  if (_inkCache.has(hex)) return _inkCache.get(hex);
  const c = hex.replace('#', '');
  const lum = [0, 2, 4]
    .map((i) => parseInt(c.slice(i, i + 2), 16) / 255)
    .map((v) => (v <= 0.04045 ? v / 12.92 : ((v + 0.055) / 1.055) ** 2.4))
    .reduce((s, v, i) => s + v * [0.2126, 0.7152, 0.0722][i], 0);
  const onWhite = 1.05 / (lum + 0.05);
  const onBlack = (lum + 0.05) / 0.05;
  const ink = onBlack >= onWhite ? '#0b0b0b' : '#ffffff';
  _inkCache.set(hex, ink);
  return ink;
}

function fromRamp(step, hueFrom, hueTo) {
  const steps = hueFrom ? rampSteps(hueFrom, hueTo || hueFrom) : activeRamp();
  const bg = steps[Math.max(0, Math.min(6, step))];
  return { bg, ink: inkOn(bg) };
}

const NEUTRAL = () => ({ bg: cssVar('--neutral'), ink: cssVar('--neutral-ink') });

function daysSince(iso) {
  if (!iso) return null;
  const t = Date.parse(iso);
  if (Number.isNaN(t)) return null;
  return (Date.now() - t) / 86400000;
}

function recencyBin(iso) {
  const d = daysSince(iso);
  if (d === null) return null;
  for (let i = 0; i < RECENCY_BINS.length; i++) if (d < RECENCY_BINS[i].max) return i;
  return RECENCY_BINS.length - 1;
}

function fmtAgo(iso) {
  const d = daysSince(iso);
  if (d === null) return 'never';
  if (d < 1) return 'today';
  if (d < 2) return 'yesterday';
  if (d < 45) return `${Math.round(d)} days ago`;
  if (d < 365) return `${Math.round(d / 30.4)} months ago`;
  const y = d / 365.25;
  return `${y < 1.95 ? '1 year' : `${Math.round(y)} years`} ago`;
}

function fmtDate(iso) {
  if (!iso) return '—';
  return new Date(iso).toLocaleDateString(undefined, { year: 'numeric', month: 'short', day: 'numeric' });
}

function num(n) {
  return n === null || n === undefined ? '—' : n.toLocaleString();
}

function verdict(key) {
  return state.verdicts[key] || {};
}

/* Detection gets provenance wrong sometimes — GitHub does not flag every
 * clone as a fork (docker-zulip is nobody's fork by the API and 1,000 commits
 * of somebody else's work by any honest reading). Your override wins. */
function provenanceOf(r) {
  return verdict(r.key).provenance || r.provenance;
}

function provRec(r) {
  return PROVENANCE.find((x) => x.id === provenanceOf(r)) || PROVENANCE[3];
}

/** Commits credited to you, after any manual disowning. */
function effortOf(r) {
  return verdict(r.key).disown ? 0 : (r.effort || 0);
}

/* ------------------------------------------------------------ scoring */

function sizeValue(r) {
  switch (state.filters.size) {
    case 'commits': return Math.max(r.commits || 0, 1);
    case 'sqrt-commits': return Math.sqrt(Math.max(r.commits || 0, 1));
    case 'issues': return Math.max(r.openIssues || 0, 1);
    case 'sqrt-issues': return Math.sqrt(Math.max(r.openIssues || 0, 1));
    case 'sqrt-files': return Math.sqrt(Math.max(r.trackedFiles || 0, 1));
    case 'equal': return 1;
    case 'sqrt-effort':
    default: return Math.sqrt(Math.max(effortOf(r), 1));
  }
}

function issueBin(n) {
  if (n === null || n === undefined) return null;
  for (let i = 0; i < ISSUE_BINS.length; i++) if (n < ISSUE_BINS[i].max) return i;
  return ISSUE_BINS.length - 1;
}

/* Fixed age brackets flatten a set that is all recent or all ancient — every
 * tile lands in one bucket and the map goes one colour. So by default the
 * scale is normalised to whatever you are actually looking at: equal-frequency
 * bins over the visible set, which guarantees the full ramp gets used.
 * The legend states the real dates at the boundaries so "green" still means
 * something you can name. */
function rebuildRecencyScale(repos) {
  const times = repos
    .map((r) => (r.lastActivity ? Date.parse(r.lastActivity) : null))
    .filter((t) => t !== null && !Number.isNaN(t))
    .sort((a, b) => a - b);
  state.recencyScale = times.length ? times : null;
}

/** Recency as a ramp step: 6 = most recent in this set, 0 = oldest. */
function recencyStep(r) {
  if (state.filters.scale === 'fixed' || !state.recencyScale) {
    const bin = recencyBin(r.lastActivity);
    return bin === null ? null : RECENCY_BINS.length - 1 - bin;
  }
  if (!r.lastActivity) return null;
  const t = Date.parse(r.lastActivity);
  if (Number.isNaN(t)) return null;
  const arr = state.recencyScale;
  // Rank of this timestamp within the visible set -> equal-frequency bin.
  let lo = 0, hi = arr.length;
  while (lo < hi) { const mid = (lo + hi) >> 1; if (arr[mid] < t) lo = mid + 1; else hi = mid; }
  return Math.max(0, Math.min(6, Math.floor((lo / Math.max(1, arr.length - 1)) * 6.999)));
}

/** Boundary dates of the auto scale, for the legend. */
function recencyScaleLabels() {
  const arr = state.recencyScale;
  if (!arr || !arr.length) return null;
  return { oldest: new Date(arr[0]).toISOString(), newest: new Date(arr[arr.length - 1]).toISOString() };
}

function colorFor(r) {
  const v = verdict(r.key);
  switch (state.filters.color) {
    case 'status': {
      const s = STATUSES.find((x) => x.id === v.status);
      return s ? fromRamp(s.step) : NEUTRAL();
    }
    case 'provenance': {
      const p = provRec(r);
      return { bg: cssVar(p.varName), ink: cssVar(p.ink) };
    }
    // Bivariate: hue says whose it is, lightness says how recently you touched
    // it. Only three hues, which is exactly the all-pairs ceiling.
    case 'prov-recency': {
      const p = provRec(r);
      const step = recencyStep(r);
      return step === null ? NEUTRAL() : fromRamp(step, p.hue, p.hueTo);
    }
    case 'issues': {
      const bin = issueBin(r.openIssues);
      return bin === null ? NEUTRAL() : fromRamp(bin);
    }
    case 'priority': {
      const step = { 3: 6, 2: 4, 1: 2 }[v.priority];
      return step === undefined ? NEUTRAL() : fromRamp(step);
    }
    case 'recency':
    default: {
      const step = recencyStep(r);
      return step === null ? NEUTRAL() : fromRamp(step);
    }
  }
}

function groupOf(r) {
  switch (state.filters.group) {
    case 'provenance': {
      const p = provRec(r);
      return p.label;
    }
    case 'status': {
      const s = STATUSES.find((x) => x.id === verdict(r.key).status);
      return s ? s.label : 'Unsorted';
    }
    case 'presence': return PRESENCE_LABEL[r.presence] || r.presence;
    case 'language': return r.language || 'No language detected';
    case 'visibility': {
      const x = VISIBILITY.find((y) => y.id === visibilityOf(r));
      return `${x.glyph} ${x.label}`;
    }
    case 'none': return `All ${state.repos.length} projects`;
    case 'owner':
    default: return r.group || 'Unaffiliated';
  }
}

function statusGlyph(r) {
  const s = STATUSES.find((x) => x.id === verdict(r.key).status);
  return s ? s.glyph : '';
}

function isStale(r) {
  const v = verdict(r.key);
  if (!v.markedAt || !v.seenLastCommit || !r.lastActivity) return false;
  return Date.parse(r.lastActivity) > Date.parse(v.seenLastCommit);
}

/* ---------------------------------------------------------- filtering */

function passesVisibility(r) {
  const vis = visibilityOf(r);
  switch (state.filters.visibility) {
    case 'all': return true;
    case 'parked': return vis !== 'visible';
    case 'hidden': return vis === 'hidden';
    case 'ignored': return vis === 'ignored';
    case 'visible':
    default: return vis === 'visible';
  }
}

function visibleRepos() {
  const q = state.filters.search.trim().toLowerCase();
  return state.repos.filter((r) => {
    if (!passesVisibility(r)) return false;
    if (!q) return true;
    const v = verdict(r.key);
    const hay = [
      r.name, r.owner, r.path, r.language, r.description, r.slug,
      ...(r.topics || []), ...(v.tags || []), v.note, v.hiddenReason,
    ].filter(Boolean).join(' ').toLowerCase();
    return hay.includes(q);
  });
}

/* ----------------------------------------------------------- squarify */

function worstRatio(row, sum, short) {
  let max = -Infinity, min = Infinity;
  for (const it of row) { if (it.area > max) max = it.area; if (it.area < min) min = it.area; }
  const s2 = sum * sum, l2 = short * short;
  return Math.max((l2 * max) / s2, s2 / (l2 * min));
}

/** Squarified treemap. Mutates each item, adding .rect. */
function squarify(items, rect) {
  const r = { ...rect };
  let i = 0;
  while (i < items.length) {
    if (r.w <= 0.01 || r.h <= 0.01) {
      for (; i < items.length; i++) items[i].rect = { x: r.x, y: r.y, w: 0, h: 0 };
      return;
    }
    const short = Math.min(r.w, r.h);
    const row = [items[i]];
    let sum = items[i].area;
    let best = worstRatio(row, sum, short);
    let j = i + 1;
    while (j < items.length) {
      const nextSum = sum + items[j].area;
      row.push(items[j]);
      const nextWorst = worstRatio(row, nextSum, short);
      if (nextWorst > best) { row.pop(); break; }
      sum = nextSum;
      best = nextWorst;
      j++;
    }
    if (r.w >= r.h) {
      const rw = sum / r.h;
      let cy = r.y;
      for (const it of row) {
        const ih = it.area / rw;
        it.rect = { x: r.x, y: cy, w: rw, h: ih };
        cy += ih;
      }
      r.x += rw; r.w -= rw;
    } else {
      const rh = sum / r.w;
      let cx = r.x;
      for (const it of row) {
        const iw = it.area / rh;
        it.rect = { x: cx, y: r.y, w: iw, h: rh };
        cx += iw;
      }
      r.y += rh; r.h -= rh;
    }
    i = j;
  }
}

function layoutInto(nodes, rect) {
  const total = nodes.reduce((s, n) => s + n.value, 0);
  if (total <= 0 || rect.w <= 0 || rect.h <= 0) return [];
  const scale = (rect.w * rect.h) / total;
  const items = nodes
    .slice()
    .sort((a, b) => b.value - a.value)
    .map((n) => ({ node: n, area: n.value * scale }));
  squarify(items, rect);
  return items;
}

/* ------------------------------------------------------------- render */

const GROUP_HEAD = 24;
const GROUP_PAD = 4;
const GROUP_GAP = 9; // gutter between organizations — structural, not decorative

function render() {
  if ($('#btn-table').getAttribute('aria-pressed') === 'true') {
    rebuildRecencyScale(visibleRepos());
    renderLegend();
    renderTable();
    return;
  }
  // renderTreemap rebuilds the scale from exactly what it draws — focus
  // included — then renders the legend, so the ramp and its stated range
  // always describe the same set.
  renderTreemap();
}

function renderTreemap() {
  const host = $('#treemap');
  host.innerHTML = '';
  state.undrawn = [];
  const repos = visibleRepos();

  if (!repos.length) {
    host.innerHTML = '<p class="empty-note">Nothing matches those filters.</p>';
    return;
  }

  const byGroup = new Map();
  for (const r of repos) {
    const g = groupOf(r);
    if (!byGroup.has(g)) byGroup.set(g, []);
    byGroup.get(g).push(r);
  }

  let groups = [...byGroup.entries()].map(([name, rs]) => ({
    name,
    repos: rs,
    value: rs.reduce((s, r) => s + sizeValue(r), 0),
  }));

  /* Focused groups expand to fill the map. The rest are NOT hidden — they
   * minimize to the dock, still named and one click from coming back. That
   * is what makes focus a selection rather than a trapdoor: you can always
   * add a second organization, because you can still see it. */
  const focus = focusSet();
  const totalGroups = groups.length;
  let parked = [];
  let focusApplied = false;
  if (focus.size) {
    const kept = groups.filter((g) => focus.has(g.name));
    if (kept.length) {
      parked = groups.filter((g) => !focus.has(g.name));
      groups = kept;
      focusApplied = true;
    }
  }
  // Populate the dock BEFORE measuring, since it takes height from the map.
  renderDock(parked);
  // Only claim focus when it actually filtered something — a search that
  // excludes the focused org would otherwise show "Focused on 16 of 16".
  renderFocusChip(focusApplied ? groups.length : 0, totalGroups, focusApplied);

  // Normalise the recency ramp over exactly the projects being drawn: focus on
  // one org and the colours re-spread across that org's own history.
  rebuildRecencyScale(groups.flatMap((g) => g.repos));
  renderLegend();

  const W = host.clientWidth;
  const H = host.clientHeight;
  const placed = layoutInto(groups, { x: 0, y: 0, w: W, h: H });

  const frag = document.createDocumentFragment();

  for (const g of placed) {
    const { x, y, w, h } = g.rect;
    const gw = Math.max(w - GROUP_GAP, 0);
    const gh = Math.max(h - GROUP_GAP, 0);
    if (gw < 6 || gh < 6) continue;

    const box = document.createElement('div');
    box.className = 'group';
    box.style.cssText = `left:${x}px;top:${y}px;width:${gw}px;height:${gh}px`;

    /* Group headers scale like tile labels do. A one-repo org in a sliver
     * should not spend 24px and 12pt on its name — that reads as a bug and
     * steals the room its own tiles need. */
    /* Same measured fit as the tiles, but solved for name AND count pill
     * together — the count is part of the header, not a bonus, so it shrinks
     * with the name rather than being dropped at an arbitrary threshold. */
    const gName = g.node.name;
    const gCount = String(g.node.repos.length);
    const head = fitHeader(gName, gCount, gw, gh);
    const { size: headSize, headH, padPx, gapPx, showCount } = head;

    const headEl = document.createElement('div');
    headEl.className = 'group-head' + (focus.has(gName) ? ' is-focused' : '');
    headEl.dataset.group = gName;
    headEl.setAttribute('role', 'button');
    headEl.tabIndex = 0;
    headEl.style.cssText =
      `height:${headH}px;font-size:${headSize}px;padding:0 ${padPx}px;gap:${gapPx}px`;
    headEl.innerHTML =
      `<span class="group-name">${escapeHTML(gName)}</span>` +
      (showCount ? `<span class="group-count">${gCount}</span>` : '');
    headEl.title = focus.has(gName)
      ? `${gName} — ${g.node.repos.length} projects. Click to minimize it to the dock.`
      : `${gName} — ${g.node.repos.length} projects. Click to focus; the rest minimize to the dock.`;
    box.appendChild(headEl);

    const pad = headSize < 8 ? 2 : GROUP_PAD;
    const inner = {
      x: pad,
      y: headH,
      w: gw - pad * 2,
      h: gh - headH - pad,
    };

    if (inner.w > 4 && inner.h > 4) {
      const nodes = g.node.repos.map((r) => ({ repo: r, value: sizeValue(r) }));
      for (const item of layoutInto(nodes, inner)) {
        const tile = buildTile(item.node.repo, item.rect);
        if (tile) box.appendChild(tile);
        else state.undrawn.push(item.node.repo);
      }
    } else {
      state.undrawn.push(...g.node.repos);
    }
    frag.appendChild(box);
  }

  host.appendChild(frag);
  correctOverflow(host);
  renderUndrawnNote();
}

/**
 * Estimating how CSS will wrap a string is a losing game — break rules,
 * hyphenation, kerning and ragged edges all conspire, and the estimate was
 * running 1–2 lines short on names like "awesome-mcp-servers". So the
 * estimate is only the opening guess: measure what the browser actually did
 * and shrink whatever overflowed.
 *
 * Reads and writes are batched into separate phases, so this costs a handful
 * of reflows for the whole map rather than one per tile.
 */
function correctOverflow(host, maxPasses = 6) {
  const names = [...host.querySelectorAll('.tile-name')];
  const heads = [...host.querySelectorAll('.group-head')];

  for (let pass = 0; pass < maxPasses; pass++) {
    // ---- read phase: no mutation, so layout is computed once ----
    const work = [];
    for (const el of names) {
      if (el.dataset.ok) continue;
      const over = el.scrollHeight - el.clientHeight;
      if (over > 0.5 && el.clientHeight > 0) {
        work.push({ el, ratio: el.clientHeight / el.scrollHeight, kind: 'tile' });
      } else {
        el.dataset.ok = '1';
      }
    }
    for (const head of heads) {
      if (head.dataset.ok) continue;
      const name = head.querySelector('.group-name');
      const over = name.scrollWidth - name.clientWidth;
      if (over > 0.5 && name.clientWidth > 0) {
        work.push({ el: head, name, ratio: name.clientWidth / name.scrollWidth, kind: 'head' });
      } else {
        head.dataset.ok = '1';
      }
    }
    if (!work.length) break;

    // ---- write phase ----
    for (const w of work) {
      const cur = parseFloat(w.el.style.fontSize);
      // Ease toward the measured ratio rather than jumping to it: overshooting
      // makes tiny text on tiles that only just overflowed.
      const next = Math.max(4, +(cur * Math.max(0.55, Math.sqrt(w.ratio) * 0.97)).toFixed(2));
      if (next >= cur - 0.01) { w.el.dataset.ok = '1'; continue; }
      // Font only. The header's height is already baked into the tile layout
      // below it, so changing it here would leave a gap or an overlap.
      w.el.style.fontSize = `${next}px`;
    }
  }

  /* Anything still overflowing has hit the 4px floor: the box is simply too
   * small to label. A name cut off mid-word is worse than no name — the tile
   * is still hoverable and clickable, and the tooltip has everything. */
  for (const el of names) {
    if (el.scrollHeight > el.clientHeight + 0.5) {
      el.style.display = 'none';
      const sub = el.parentElement.querySelector('.tile-sub');
      if (sub) sub.style.display = 'none';
    }
  }
}

function renderDock(parked) {
  const dock = $('#dock');
  if (!dock) return;
  if (!parked.length) { dock.hidden = true; dock.innerHTML = ''; return; }
  dock.hidden = false;
  dock.innerHTML =
    `<span class="dock-label">Minimized</span>` +
    parked
      .slice()
      .sort((a, b) => b.repos.length - a.repos.length)
      .map((g) => `<button type="button" class="dock-chip" data-group="${escapeHTML(g.name)}"
        title="Bring ${escapeHTML(g.name)} back into focus">${escapeHTML(g.name)}
        <span class="group-count">${g.repos.length}</span></button>`)
      .join('');
}

function renderFocusChip(shown, total, applied = true) {
  const el = $('#focus-chip');
  if (!el) return;
  const s = focusSet();
  if (!s.size || !applied) { el.hidden = true; return; }
  el.hidden = false;
  el.innerHTML =
    `<span>Focused on ${shown} of ${total}: ${escapeHTML([...s].join(', '))}</span>` +
    `<button type="button" id="focus-clear" aria-label="Show all groups">show all</button>`;
  el.querySelector('#focus-clear').addEventListener('click', (e) => {
    e.stopPropagation();
    clearFocus();
  });
}

/* A project too small to get a pixel is still a project. Saying so beats
 * letting the map imply the portfolio is smaller than it is. */
function renderUndrawnNote() {
  const el = $('#undrawn');
  if (!el) return;
  const n = state.undrawn.length;
  if (!n) { el.hidden = true; return; }
  el.hidden = false;
  el.textContent = `${n} too small to draw — ${state.undrawn
    .slice(0, 3).map((r) => r.name).join(', ')}${n > 3 ? '…' : ''}`;
  el.title = state.undrawn.map((r) => r.name).join('\n');
}

/**
 * Solve a group header: the largest size at which the org name AND its count
 * pill both fit one line, inside a bar that never eats more than a third of
 * the block. Only if the name alone cannot fit at the floor does the pill go.
 */
function fitHeader(name, count, gw, gh) {
  const maxH = Math.max(8, Math.round(gh * 0.34));
  // .group-head carries letter-spacing:0.01em, and the pill has 6px side
  // padding plus a 1px border either side. Under-count either and the name
  // ends up in an ellipsis.
  const track = 0.01 * name.length;
  const nUnit = unitWidth(name, 700) + track;
  const cUnit = unitWidth(count, 600);
  const SLACK = 2;

  for (let s = 12; s >= 4; s -= 0.25) {
    const padPx = s < 8 ? 2 : s < 10 ? 5 : 9;
    const gapPx = s < 8 ? 2 : 6;
    const hh = Math.min(Math.round(s * 2), maxH);
    if (hh < s * 1.15) continue; // no vertical room for this size
    const pillW = cUnit * s * 0.82 + (s < 8 ? 10 : 16);
    if (padPx * 2 + nUnit * s + gapPx + pillW + SLACK <= gw) {
      return { size: +s.toFixed(2), headH: hh, padPx, gapPx, showCount: true };
    }
  }
  // Name alone, still measured.
  for (let s = 12; s >= 4; s -= 0.25) {
    const padPx = s < 8 ? 2 : 5;
    const hh = Math.min(Math.round(s * 2), maxH);
    if (hh < s * 1.15) continue;
    if (padPx * 2 + nUnit * s + SLACK <= gw) {
      return { size: +s.toFixed(2), headH: hh, padPx, gapPx: 2, showCount: false };
    }
  }
  return { size: 4, headH: Math.max(8, Math.min(9, maxH)), padPx: 1, gapPx: 1, showCount: false };
}

function buildTile(r, rect) {
  const w = Math.max(rect.w - 2, 0);
  const h = Math.max(rect.h - 2, 0);
  if (w < 2 || h < 2) return null;

  const v = verdict(r.key);
  const { bg, ink } = colorFor(r);

  const vis = visibilityOf(r);
  const el = document.createElement('div');
  el.className = 'tile';
  if (r.presence !== 'both') el.classList.add(`presence-${r.presence}`);
  if (vis !== 'visible') el.classList.add(`is-${vis}-row`);
  if (r.key === state.selectedKey) el.classList.add('is-selected');

  const flags = [
    vis !== 'visible' ? VISIBILITY.find((x) => x.id === vis).glyph : '',
    statusGlyph(r),
    v.priority ? ['', '▁', '▄', '█'][v.priority] : '',
    v.provenance ? '✎' : '',
    r.duplicateOf ? '⧉' : '',
    r.dirtyFiles ? '✱' : '',
    r.unpushedCommits ? '↑' : '',
    r.isArchived ? '▤' : '',
  ].filter(Boolean).join(' ');

  // The subtitle tracks whatever the map is currently sized or coloured by,
  // so the number on the tile is the number you are looking at.
  const byIssues = /issues/.test(state.filters.size) || state.filters.color === 'issues';
  const lead = byIssues
    ? `${num(r.openIssues)} iss`
    : `${num(state.filters.size === 'sqrt-effort' ? effortOf(r) : r.commits)}`;
  const subText = `${lead} · ${fmtAgo(r.lastActivity)}`;

  /* Fit the real name to the real box. Padding shrinks first, because on a
   * small tile 5px of padding is most of the tile. */
  const padX = w < 26 ? 1 : w < 60 ? 3 : 5;
  const padY = h < 18 ? 1 : 3;
  const iw = w - padX * 2;
  const ih = h - padY * 2;
  const showText = iw >= 6 && ih >= 5;

  const nameFit = showText
    ? fitText(r.name, iw, ih, { min: 4, max: 13, weight: 600, maxLines: ih > 26 ? 3 : 2 })
    : { size: 4, lines: 1, fits: false };

  const nameH = nameFit.lines * nameFit.size * 1.15;
  // A subtitle only earns its place if it fits under the name at a size that
  // is still readable, and doesn't crowd the name it belongs to.
  const subFit = showText && ih - nameH - 2 > 0
    ? fitText(subText, iw, ih - nameH - 2,
        { min: 5, max: Math.max(5, Math.min(10, nameFit.size * 0.85)), weight: 400, maxLines: 1 })
    : { size: 5, fits: false };
  const showSub = showText && nameFit.fits && subFit.fits;
  const showFlags = showText && nameFit.fits && w >= 40 && ih - nameH >= 11;
  // Give the name every pixel the subtitle isn't using, so a wrap that lands
  // one line deeper than estimated still shows rather than being cut off.
  const nameMaxH = Math.max(0, ih - (showSub ? subFit.size * 1.15 + 2 : 0));

  el.style.cssText =
    `left:${rect.x}px;top:${rect.y}px;width:${w}px;height:${h}px;` +
    `padding:${padY}px ${padX}px;background:${bg};color:${ink}`;
  el.dataset.key = r.key;
  el.tabIndex = 0;
  el.setAttribute('role', 'button');
  el.setAttribute('aria-label',
    `${r.name}, ${r.owner || 'no owner'}, ${num(r.commits)} commits, last work ${fmtAgo(r.lastActivity)}` +
    (v.status ? `, marked ${v.status}` : '') + (vis !== 'visible' ? `, ${vis}` : ''));

  el.innerHTML = showText
    ? `<div class="tile-name" style="font-size:${nameFit.size}px;max-height:${nameMaxH.toFixed(1)}px">${escapeHTML(r.name)}</div>` +
      (showSub ? `<div class="tile-sub" style="font-size:${subFit.size}px">${escapeHTML(subText)}</div>` : '') +
      (flags && showFlags ? `<div class="tile-flags" style="font-size:${Math.min(9, subFit.size)}px">${escapeHTML(flags)}</div>` : '')
    : '';

  return el;
}

function escapeHTML(s) {
  return String(s == null ? '' : s).replace(/[&<>"']/g, (c) =>
    ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
}

/* ------------------------------------------------------------- legend */

function renderLegend() {
  const host = $('#legend-body');
  const parts = [];
  const mode = state.filters.color;

  const ramp = (steps, h, h2) => {
    const cols = h ? rampSteps(h, h2 || h) : activeRamp();
    return `<span class="legend-ramp">${steps
      .map((s) => `<span class="legend-swatch" style="background:${cols[s]}"></span>`)
      .join('')}</span>`;
  };
  const unsorted = (label) =>
    `<span class="legend-item"><span class="legend-swatch" style="background:var(--neutral)"></span>${label}</span>`;

  // With an auto scale the ends are real dates from this set, not fixed
  // brackets — so name them, or "green" means nothing you can act on.
  const bounds = recencyScaleLabels();
  const recencyRange = state.filters.scale === 'auto' && bounds
    ? `${escapeHTML(fmtAgo(bounds.oldest))} &rarr; ${escapeHTML(fmtAgo(bounds.newest))}` +
      ` <span class="legend-note">(spread across these ${state.recencyScale.length})</span>`
    : '2 yrs + &rarr; past week <span class="legend-note">(fixed brackets)</span>';

  if (mode === 'recency') {
    parts.push(
      `<span class="legend-label">Last work</span>${ramp([0, 1, 2, 3, 4, 5, 6])}` +
      `<span class="legend-note">${recencyRange}</span>` + unsorted('never')
    );
  } else if (mode === 'prov-recency') {
    parts.push(
      `<span class="legend-label">Whose &times; last work</span>` +
      PROVENANCE.slice(0, 3).map((p) =>
        `<span class="legend-item">${ramp([0, 2, 4, 6], p.hue, p.hueTo)}${p.glyph} ${p.label}</span>`
      ).join('') +
      `<span class="legend-note">${recencyRange}</span>`
    );
  } else if (mode === 'issues') {
    parts.push(
      `<span class="legend-label">Open issues</span>${ramp([0, 1, 2, 3, 4, 5, 6])}` +
      `<span class="legend-note">none &rarr; 100 +</span>` + unsorted('not on GitHub')
    );
  } else if (mode === 'status') {
    parts.push('<span class="legend-label">Status</span>' + STATUSES.map((s) =>
      `<span class="legend-item"><span class="legend-swatch" style="background:${activeRamp()[s.step]}"></span>${s.glyph} ${s.label}</span>`
    ).join('') + unsorted('Unsorted'));
  } else if (mode === 'provenance') {
    parts.push('<span class="legend-label">Provenance</span>' + PROVENANCE.map((p) =>
      `<span class="legend-item"><span class="legend-swatch" style="background:var(${p.varName})"></span>${p.glyph} ${p.label}</span>`
    ).join(''));
  } else if (mode === 'priority') {
    parts.push('<span class="legend-label">Priority</span>' +
      [[6, 'High'], [4, 'Medium'], [2, 'Low']].map(([step, label]) =>
        `<span class="legend-item"><span class="legend-swatch" style="background:${activeRamp()[step]}"></span>${label}</span>`
      ).join('') + unsorted('Unset'));
  }

  const sizeLabel = {
    'sqrt-effort': 'Area = √ commits by you (compressed; forks and clones shrink away)',
    'sqrt-commits': 'Area = √ all commits across every branch, including other people’s',
    commits: 'Area = all commits, linear (true proportion)',
    'sqrt-issues': 'Area = √ open issues',
    issues: 'Area = open issues, linear',
    'sqrt-files': 'Area = √ tracked files',
    equal: 'Area = equal (all tiles same size)',
  }[state.filters.size];

  parts.push(
    `<span class="legend-note">${sizeLabel}</span>` +
    `<span class="legend-item legend-note">` +
    `<span class="legend-swatch" style="background:transparent;border-style:dashed;border-color:var(--text-primary)"></span>local only` +
    `</span>` +
    `<span class="legend-item legend-note">` +
    `<span class="legend-swatch" style="background:transparent;border-style:dotted;border-color:var(--text-primary)"></span>not cloned` +
    `</span>` +
    `<span class="legend-note">✱ uncommitted · ↑ unpushed · ▤ archived</span>`
  );

  host.innerHTML = parts.join('<span></span>');
}

/* -------------------------------------------------------------- table */

const TABLE_COLS = [
  { key: 'name', label: 'Project' },
  { key: 'owner', label: 'Org' },
  { key: 'provenance', label: 'Provenance' },
  { key: 'presence', label: 'Where' },
  { key: 'commits', label: 'Commits', num: true },
  { key: 'lastActivity', label: 'Last work' },
  { key: 'openIssues', label: 'Issues', num: true },
  { key: 'openPRs', label: 'PRs', num: true },
  { key: 'status', label: 'Status' },
  { key: 'priority', label: 'Priority' },
  { key: 'visibility', label: 'Showing' },
  { key: 'tags', label: 'Tags' },
];

function renderTable() {
  const rows = visibleRepos().slice();
  const col = state.sortCol;
  rows.sort((a, b) => {
    const av = tableValue(a, col), bv = tableValue(b, col);
    if (av === bv) return a.name.localeCompare(b.name);
    if (av === null || av === undefined) return 1;
    if (bv === null || bv === undefined) return -1;
    return (av > bv ? 1 : -1) * state.sortDir;
  });

  $('#table-body').innerHTML = rows.map((r) => {
    const v = verdict(r.key);
    const s = STATUSES.find((x) => x.id === v.status);
    const p = provRec(r);
    const x = VISIBILITY.find((y) => y.id === visibilityOf(r));
    return `<tr data-key="${escapeHTML(r.key)}">
      <td>${escapeHTML(r.name)}${r.duplicateOf ? ' <span class="muted">⧉ copy</span>' : ''}</td>
      <td>${escapeHTML(r.owner || '—')}</td>
      <td>${p.glyph} ${escapeHTML(p.label)}${v.provenance ? ' ✎' : ''}</td>
      <td>${escapeHTML(PRESENCE_LABEL[r.presence] || r.presence)}</td>
      <td class="num">${num(r.commits)}</td>
      <td>${escapeHTML(fmtAgo(r.lastActivity))}</td>
      <td class="num">${num(r.openIssues)}</td>
      <td class="num">${num(r.openPRs)}</td>
      <td>${s ? `${s.glyph} ${escapeHTML(s.label)}` : '—'}</td>
      <td>${escapeHTML(PRIORITY_LABEL[v.priority || 0])}</td>
      <td>${x.glyph} ${escapeHTML(x.label)}${v.hiddenReason ? ` <span class="muted">— ${escapeHTML(v.hiddenReason)}</span>` : ''}</td>
      <td>${escapeHTML((v.tags || []).join(', ') || '—')}</td>
    </tr>`;
  }).join('');
}

function tableValue(r, col) {
  const v = verdict(r.key);
  // Sort by meaningful rank, not alphabetically: "Active" before "Dead",
  // "Ignored" grouped at one end.
  if (col === 'status') {
    const s = STATUSES.findIndex((x) => x.id === v.status);
    return s === -1 ? -1 : STATUSES.length - s;
  }
  if (col === 'visibility') return VISIBILITY.findIndex((x) => x.id === visibilityOf(r));
  if (col === 'provenance') return provenanceOf(r);
  if (col === 'priority') return v.priority || 0;
  if (col === 'tags') return (v.tags || []).join(',');
  return r[col];
}

/* -------------------------------------------------------------- panel */

function openPanel(key) {
  state.selectedKey = key;
  const r = state.repos.find((x) => x.key === key);
  if (!r) return;
  const v = verdict(key);

  const stale = isStale(r);
  const p = provRec(r);

  $('#panel-body').innerHTML = `
    <h2>${escapeHTML(r.name)}</h2>
    <div class="panel-org">${escapeHTML(r.slug || r.path || '')} · ${p.glyph} ${escapeHTML(p.label)}
      · ${escapeHTML(PRESENCE_LABEL[r.presence] || r.presence)}${r.isArchived ? ' · archived' : ''}</div>
    ${r.description ? `<p class="panel-desc">${escapeHTML(r.description)}</p>` : ''}

    <div class="stat-row">
      <div class="stat"><div class="stat-label">Commits (all refs)</div>
        <div class="stat-value">${num(r.commits)}
          ${r.myCommits && r.commits ? `<small>${Math.round(r.myCommitShare * 100)}% yours</small>` : ''}</div></div>
      <div class="stat"><div class="stat-label">Last work</div>
        <div class="stat-value" style="font-size:14px">${escapeHTML(fmtAgo(r.lastActivity))}</div></div>
      <div class="stat"><div class="stat-label">Open issues</div>
        <div class="stat-value">${num(r.openIssues)}<small> · ${num(r.openPRs)} pr</small></div></div>
    </div>

    ${stale ? `<div class="stale">⚠ <strong>Your call here may be out of date.</strong>
      You marked this ${escapeHTML(fmtDate(v.markedAt))}. There has been new work since —
      the newest commit is now ${escapeHTML(fmtDate(r.lastActivity))}
      (${escapeHTML(fmtAgo(r.lastActivity))}), where it was
      ${escapeHTML(fmtDate(v.seenLastCommit))} when you judged it.</div>` : ''}

    ${r.duplicateOf ? `<div class="dup-note">⧉ <strong>This is a second working copy.</strong>
      ${r.clonesOfSlug} folders on this machine point at <code>${escapeHTML(r.slug)}</code>.
      Issue and PR counts are attributed to the copy with the most history, so they
      show as — here. A good candidate to hide.</div>` : ''}

    <div class="panel-section">
      <h3>Status</h3>
      <div class="seg" id="seg-status">
        ${STATUSES.map((s) => `<button type="button" data-status="${s.id}" aria-pressed="${v.status === s.id}">
          <span class="dot" style="background:${activeRamp()[s.step]}"></span>${s.glyph} ${s.label}</button>`).join('')}
        <button type="button" data-status="" aria-pressed="${!v.status}">Unsorted</button>
      </div>
    </div>

    <div class="panel-section">
      <h3>Priority</h3>
      <div class="seg" id="seg-priority">
        ${[3, 2, 1, 0].map((n) =>
          `<button type="button" data-priority="${n}" aria-pressed="${(v.priority || 0) === n}">${PRIORITY_LABEL[n]}</button>`).join('')}
      </div>
    </div>

    <div class="panel-section">
      <h3>Showing</h3>
      <div class="seg" id="seg-visibility">
        ${VISIBILITY.map((x) => `<button type="button" data-visibility="${x.id}"
          aria-pressed="${visibilityOf(r) === x.id}">${x.glyph} ${x.label}</button>`).join('')}
      </div>
      <p class="seg-help">Hidden is “off my screen for now”. Ignored is “not my project,
      stop counting it”. Both stay reachable — set <em>Showing</em> in the toolbar to
      <em>Only hidden + ignored</em>, or sort the table by this column.</p>
      ${visibilityOf(r) !== 'visible' ? `<div style="margin-top:7px">
        <input type="text" id="hide-reason" placeholder="Why? (searchable)"
               value="${escapeHTML(v.hiddenReason || '')}" list="tag-suggestions">
      </div>` : ''}
    </div>

    <div class="panel-section">
      <h3>Provenance ${v.provenance ? '<span class="override-flag">✎ overridden</span>' : ''}</h3>
      <div class="seg" id="seg-provenance">
        ${PROVENANCE.slice(0, 3).map((p) => `<button type="button" data-provenance="${p.id}"
          aria-pressed="${provenanceOf(r) === p.id}">
          <span class="dot" style="background:var(${p.varName})"></span>${p.glyph} ${p.label}</button>`).join('')}
        <button type="button" data-provenance="" aria-pressed="${!v.provenance}">Auto-detect</button>
      </div>
      <p class="seg-help">Detected as <strong>${escapeHTML((PROVENANCE.find((x) => x.id === r.provenance) || PROVENANCE[3]).label)}</strong>${r.isFork ? ' (GitHub says fork)' : ''}.</p>
      <label class="check-row">
        <input type="checkbox" id="chk-disown" ${v.disown ? 'checked' : ''}>
        <span>Don’t count its ${num(r.effort)} commits as my work</span>
      </label>
    </div>

    <div class="panel-section">
      <h3>Tags</h3>
      <div class="tag-list" id="tag-list">
        ${(v.tags || []).map((t) => `<span class="tag">${escapeHTML(t)}
          <button type="button" data-untag="${escapeHTML(t)}" aria-label="Remove ${escapeHTML(t)}">×</button></span>`).join('')
          || '<span class="muted">none</span>'}
      </div>
      <input type="text" id="tag-input" placeholder="Add a tag, press Enter" list="tag-suggestions">
      <datalist id="tag-suggestions">${COMMON_TAGS.map((t) => `<option value="${t}">`).join('')}</datalist>
    </div>

    <div class="panel-section">
      <h3>Note</h3>
      <textarea id="note-input" placeholder="What is this, why does it matter, what's next…">${escapeHTML(v.note || '')}</textarea>
    </div>

    <div class="panel-links">
      ${r.url ? `<a href="${escapeHTML(r.url)}" target="_blank" rel="noopener">GitHub ↗</a>` : ''}
      ${r.absPath ? `<button type="button" id="btn-reveal">Reveal in Finder</button>` : ''}
    </div>

    <div class="panel-section">
      <h3>Facts</h3>
      <dl class="kv">
        <dt>Path</dt><dd>${escapeHTML(r.path || '— not cloned —')}</dd>
        <dt>Branch</dt><dd>${escapeHTML(r.branch || '—')}</dd>
        <dt>On this branch</dt><dd>${num(r.commitsHead)}</dd>
        <dt>Local branches</dt><dd>${num(r.localBranches)}</dd>
        <dt>On GitHub default</dt><dd>${num(r.remoteCommits)}</dd>
        <dt>First commit</dt><dd>${escapeHTML(fmtDate(r.firstCommitDate))}</dd>
        <dt>Last commit</dt><dd>${escapeHTML(fmtDate(r.lastCommitDate))}</dd>
        <dt>Commits 90d</dt><dd>${num(r.commits90d)}</dd>
        <dt>Tracked files</dt><dd>${num(r.trackedFiles)}</dd>
        <dt>Uncommitted</dt><dd>${num(r.dirtyFiles)}</dd>
        <dt>Unpushed</dt><dd>${num(r.unpushedCommits)}</dd>
        <dt>Contributors</dt><dd>${num(r.contributors)}</dd>
        <dt>Language</dt><dd>${escapeHTML(r.language || '—')}</dd>
        <dt>Stars</dt><dd>${num(r.stars)}</dd>
        ${r.forkOf ? `<dt>Fork of</dt><dd>${escapeHTML(r.forkOf)}</dd>` : ''}
      </dl>
    </div>
  `;

  const wasHidden = $('#panel').hidden;
  $('#panel').hidden = false;
  wirePanel(r);
  // Opening the panel narrows the stage, so the map has to be re-laid out.
  if (wasHidden) renderTreemap();
  renderTreemapSelection();
}

function renderTreemapSelection() {
  document.querySelectorAll('.tile.is-selected').forEach((t) => t.classList.remove('is-selected'));
  const el = document.querySelector(`.tile[data-key="${CSS.escape(state.selectedKey || '')}"]`);
  if (el) el.classList.add('is-selected');
}

function closePanel(force = false) {
  if (state.panelPinned && !force) return;
  if ($('#panel').hidden) return;
  $('#panel').hidden = true;
  state.selectedKey = null;
  renderTreemap();
}

function setPinned(on) {
  state.panelPinned = on;
  localStorage.setItem('atlas-pin', on ? '1' : '0');
  $('#panel-pin').setAttribute('aria-pressed', String(on));
  $('#panel-pin').textContent = on ? '📌 Pinned' : '📌 Pin';
  $('#panel-pin').title = on
    ? 'Pinned — the panel stays open when you click away'
    : 'Pin the panel open (otherwise clicking away closes it)';
}

function wirePanel(r) {
  const body = $('#panel-body');

  body.querySelectorAll('#seg-status button').forEach((b) => {
    b.addEventListener('click', () => setVerdict(r, { status: b.dataset.status || undefined }));
  });
  body.querySelectorAll('#seg-priority button').forEach((b) => {
    b.addEventListener('click', () => setVerdict(r, { priority: +b.dataset.priority || undefined }));
  });

  body.querySelectorAll('#seg-visibility button').forEach((b) => {
    b.addEventListener('click', () => setVerdict(r, { visibility: b.dataset.visibility }));
  });

  body.querySelectorAll('#seg-provenance button').forEach((b) => {
    b.addEventListener('click', () => {
      const id = b.dataset.provenance || undefined;
      // Calling something "not mine" almost always means its commits shouldn't
      // count as yours — but you can uncheck that below if you did the work.
      const patch = { provenance: id };
      if (id && id !== 'mine') patch.disown = true;
      if (id === 'mine') patch.disown = false;
      setVerdict(r, patch);
    });
  });

  const disown = body.querySelector('#chk-disown');
  if (disown) disown.addEventListener('change', () => setVerdict(r, { disown: disown.checked }));

  const reason = body.querySelector('#hide-reason');
  if (reason) reason.addEventListener('change', () => setVerdict(r, { hiddenReason: reason.value }, false));

  const tagInput = body.querySelector('#tag-input');
  if (tagInput) {
    tagInput.addEventListener('keydown', (e) => {
      if (e.key !== 'Enter') return;
      e.preventDefault();
      const t = tagInput.value.trim();
      if (!t) return;
      const tags = [...new Set([...(verdict(r.key).tags || []), t])];
      setVerdict(r, { tags });
    });
  }
  body.querySelectorAll('[data-untag]').forEach((b) => {
    b.addEventListener('click', () => {
      const tags = (verdict(r.key).tags || []).filter((t) => t !== b.dataset.untag);
      setVerdict(r, { tags });
    });
  });

  const note = body.querySelector('#note-input');
  if (note) note.addEventListener('change', () => setVerdict(r, { note: note.value }, false));

  const reveal = body.querySelector('#btn-reveal');
  if (reveal) {
    reveal.addEventListener('click', () => {
      fetch('/api/open', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ absPath: r.absPath }),
      });
    });
  }
}

/* ------------------------------------------------------------ verdicts */

function setVerdict(r, patch, reopen = true) {
  const prev = state.verdicts[r.key] || {};
  const next = { ...prev, ...patch };

  if (next.visibility === 'visible') delete next.visibility; // the default
  for (const k of Object.keys(next)) {
    if (next[k] === undefined || next[k] === null || next[k] === '' ||
        (Array.isArray(next[k]) && !next[k].length) || next[k] === false) {
      delete next[k];
    }
  }

  const meaningful = Object.keys(next).some((k) => k !== 'markedAt' && k !== 'seenLastCommit');
  if (!meaningful) {
    delete state.verdicts[r.key];
  } else {
    next.markedAt = new Date().toISOString();
    next.seenLastCommit = r.lastActivity || null;
    if (!next.seenLastCommit) delete next.seenLastCommit;
    state.verdicts[r.key] = next;
  }

  scheduleSave();
  render();
  if (reopen) openPanel(r.key);
}

function scheduleSave() {
  clearTimeout(state.saveTimer);
  $('#save-state').textContent = 'unsaved…';
  state.saveTimer = setTimeout(save, 400);
}

async function save() {
  state.saving = true;
  try {
    const res = await fetch('/api/verdicts', {
      method: 'PUT',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(state.verdicts),
    });
    const json = await res.json();
    $('#save-state').textContent = res.ok
      ? `saved · ${json.count} judged`
      : `save failed: ${json.error}`;
  } catch (err) {
    $('#save-state').textContent = 'save failed: ' + err.message;
  } finally {
    state.saving = false;
  }
}

/* ------------------------------------------------------------ tooltip */

const tip = () => $('#tooltip');

function showTooltip(r, ev) {
  const v = verdict(r.key);
  const s = STATUSES.find((x) => x.id === v.status);
  const vis = visibilityOf(r);
  tip().innerHTML =
    `<div class="tt-name">${escapeHTML(r.name)}</div>` +
    `<div class="muted">${escapeHTML(r.slug || r.path || '')}</div>` +
    `<dl>
      <dt>Commits</dt><dd>${num(r.commits)}</dd>
      <dt>Last work</dt><dd>${escapeHTML(fmtAgo(r.lastActivity))}</dd>
      <dt>Open</dt><dd>${num(r.openIssues)} issues · ${num(r.openPRs)} PRs</dd>
      <dt>Where</dt><dd>${escapeHTML(PRESENCE_LABEL[r.presence] || r.presence)}</dd>
      ${s ? `<dt>Status</dt><dd>${s.glyph} ${escapeHTML(s.label)}</dd>` : ''}
      ${vis !== 'visible' ? `<dt>Showing</dt><dd>${escapeHTML(vis)}${v.hiddenReason ? ` — ${escapeHTML(v.hiddenReason)}` : ''}</dd>` : ''}
      ${v.priority ? `<dt>Priority</dt><dd>${escapeHTML(PRIORITY_LABEL[v.priority])}</dd>` : ''}
      ${r.dirtyFiles ? `<dt>Uncommitted</dt><dd>${num(r.dirtyFiles)} files</dd>` : ''}
      ${r.unpushedCommits ? `<dt>Unpushed</dt><dd>${num(r.unpushedCommits)} commits</dd>` : ''}
      ${r.duplicateOf ? `<dt>⧉</dt><dd>duplicate of another clone</dd>` : ''}
      ${isStale(r) ? `<dt>⚠</dt><dd>new work since you judged it</dd>` : ''}
    </dl>`;
  tip().hidden = false;
  moveTooltip(ev);
}

function moveTooltip(ev) {
  const t = tip();
  const pad = 14;
  const rect = t.getBoundingClientRect();
  let x = ev.clientX + pad;
  let y = ev.clientY + pad;
  if (x + rect.width > window.innerWidth - 8) x = ev.clientX - rect.width - pad;
  if (y + rect.height > window.innerHeight - 8) y = ev.clientY - rect.height - pad;
  t.style.left = `${Math.max(8, x)}px`;
  t.style.top = `${Math.max(8, y)}px`;
}

/* --------------------------------------------------------------- wire */

function repoAt(el) {
  const tileEl = el.closest('[data-key]');
  if (!tileEl) return null;
  return state.repos.find((r) => r.key === tileEl.dataset.key) || null;
}

function wireGlobal() {
  const stage = $('#stage');

  stage.addEventListener('mouseover', (e) => {
    const r = repoAt(e.target);
    if (r) showTooltip(r, e);
  });
  stage.addEventListener('mousemove', (e) => {
    if (!tip().hidden) moveTooltip(e);
  });
  stage.addEventListener('mouseout', (e) => {
    if (!e.relatedTarget || !repoAt(e.relatedTarget)) tip().hidden = true;
  });
  stage.addEventListener('click', (e) => {
    // Bring a minimized group back.
    const chip = e.target.closest('.dock-chip');
    if (chip) { toggleFocus(chip.dataset.group); return; }

    const head = e.target.closest('.group-head');
    if (head) {
      const name = head.dataset.group;
      const s = focusSet();
      if (!s.size) {
        // Nothing focused yet: this one takes the map, the rest go to the dock.
        s.add(name);
        persistFocus();
        closePanel();
        render();
      } else {
        // Already focusing: clicking a focused header minimizes it again.
        toggleFocus(name);
      }
      return;
    }
    const r = repoAt(e.target);
    if (r) openPanel(r.key);
    else closePanel(); // clicking bare map closes an unpinned panel
  });

  stage.addEventListener('keydown', (e) => {
    const head = e.target.closest && e.target.closest('.group-head');
    if (head && (e.key === 'Enter' || e.key === ' ')) {
      e.preventDefault();
      toggleFocus(head.dataset.group);
    }
  });

  $('#table-body').addEventListener('click', (e) => {
    const r = repoAt(e.target);
    if (r) openPanel(r.key);
  });

  document.querySelectorAll('#table-view th').forEach((th, i) => {
    th.addEventListener('click', () => {
      const col = TABLE_COLS[i].key;
      if (state.sortCol === col) state.sortDir *= -1;
      else { state.sortCol = col; state.sortDir = -1; }
      renderTable();
    });
  });

  $('#panel-close').addEventListener('click', () => closePanel(true));
  $('#panel-pin').addEventListener('click', () => setPinned(!state.panelPinned));

  const bind = (sel, key, transform = (v) => v) =>
    $(sel).addEventListener('input', (e) => {
      state.filters[key] = transform(e.target.type === 'checkbox' ? e.target.checked : e.target.value);
      render();
    });

  bind('#f-search', 'search');
  bind('#f-group', 'group');
  bind('#f-size', 'size');
  bind('#f-visibility', 'visibility');

  $('#f-color').addEventListener('input', (e) => {
    state.filters.color = e.target.value;
    localStorage.setItem('atlas-color', e.target.value);
    syncHueControl();
    render();
  });
  $('#f-hue').addEventListener('input', (e) => setPalette(e.target.value, state.filters.hueTo));
  $('#f-hue-to').addEventListener('input', (e) => setPalette(state.filters.hue, e.target.value));
  $('#f-preset').addEventListener('input', (e) => {
    if (!e.target.value) return;
    const [from, to] = e.target.value.split(':');
    setPalette(from, to);
    e.target.value = '';
  });
  $('#f-scale').addEventListener('input', (e) => {
    state.filters.scale = e.target.value;
    localStorage.setItem('atlas-scale', e.target.value);
    render();
  });

  $('#btn-table').addEventListener('click', (e) => {
    const on = e.target.getAttribute('aria-pressed') !== 'true';
    e.target.setAttribute('aria-pressed', String(on));
    $('#table-view').hidden = !on;
    $('#stage').hidden = on;
    render();
  });

  // Unpinned means: the panel belongs to the tile you clicked. Click anything
  // that is not a tile — bare map, legend, toolbar, footer — and it goes away.
  // Only the panel itself is exempt, so you can actually use its controls.
  document.addEventListener('mousedown', (e) => {
    if (state.panelPinned || $('#panel').hidden) return;
    // Group headers and dock chips are click targets too. Closing on THEIR
    // mousedown re-renders the treemap, which destroys the element under the
    // cursor before its click event can fire — the focus click silently
    // vanishes. Let their own click handlers close the panel instead.
    if (e.target.closest('#panel, .tile, .group-head, .dock-chip')) return;
    closePanel();
  });

  $('#btn-theme').addEventListener('click', () => {
    const next = document.documentElement.dataset.theme === 'dark' ? 'light' : 'dark';
    document.documentElement.dataset.theme = next;
    localStorage.setItem('atlas-theme', next);
    _rampCache.clear(); // ramps are stepped per mode, not inverted
    renderPaletteBadge();
    render();
  });

  $('#btn-export').addEventListener('click', () => {
    const blob = new Blob([JSON.stringify(state.verdicts, null, 2)], { type: 'application/json' });
    const a = document.createElement('a');
    a.href = URL.createObjectURL(blob);
    a.download = 'verdicts.json';
    a.click();
    URL.revokeObjectURL(a.href);
  });

  document.addEventListener('keydown', (e) => {
    const tag = document.activeElement && document.activeElement.tagName;
    if (tag === 'INPUT' || tag === 'TEXTAREA' || tag === 'SELECT') return;
    if (e.key === 'Escape') { closePanel(true); return; }
    if (!state.selectedKey || e.metaKey || e.ctrlKey || e.altKey) return;
    const r = state.repos.find((x) => x.key === state.selectedKey);
    if (!r) return;

    const map = {
      '1': () => setVerdict(r, { priority: 1 }),
      '2': () => setVerdict(r, { priority: 2 }),
      '3': () => setVerdict(r, { priority: 3 }),
      '0': () => setVerdict(r, { priority: undefined }),
      h: () => setVerdict(r, { visibility: visibilityOf(r) === 'hidden' ? 'visible' : 'hidden' }),
      i: () => setVerdict(r, { visibility: visibilityOf(r) === 'ignored' ? 'visible' : 'ignored' }),
      p: () => setPinned(!state.panelPinned),
    };
    for (const s of STATUSES) map[s.key] = () => setVerdict(r, { status: s.id });

    const fn = map[e.key.toLowerCase()];
    if (fn) { e.preventDefault(); fn(); }
  });

  let rt;
  window.addEventListener('resize', () => {
    clearTimeout(rt);
    rt = setTimeout(render, 120);
  });
}

/* --------------------------------------------------------------- boot */

/** The palette picker only drives the single-variable encodings. */
function syncHueControl() {
  const usesRamp = ['recency', 'issues', 'status', 'priority'].includes(state.filters.color);
  $('#ctl-hue').style.display = usesRamp ? '' : 'none';
  $('#ctl-scale').style.display =
    ['recency', 'prov-recency'].includes(state.filters.color) ? '' : 'none';
  renderPaletteBadge(); // cheap, and the badge must never be blank
}

/**
 * Run the real checks on whatever ramp is selected and say so. Red→green is
 * the classic colour-vision failure; it is offered because it is the clearest
 * scale for most people, but it should never ship silently.
 */
function renderPaletteBadge() {
  const badge = $('#palette-badge');
  const ramp = activeRamp();
  const { ok, checks, endsCVD, endsKind } = window.ATLAS_PALETTE.validateRamp(ramp, themeName());
  const failed = checks.filter((c) => !c.pass);
  const endsFail = failed.some((c) => c.name === 'Ends distinguishable');

  badge.className = 'palette-badge ' + (ok ? 'ok' : endsFail ? 'bad' : 'warn');
  badge.textContent = ok
    ? '✓ colour-vision safe'
    : endsFail
      ? `✕ ends merge for ${endsKind}`
      : `⚠ ${failed[0].name.toLowerCase()}`;
  badge.title = ok
    ? `All checks pass in ${themeName()} mode.\n` + checks.map((c) => `✓ ${c.name}: ${c.detail}`).join('\n')
    : `Problems in ${themeName()} mode:\n` +
      failed.map((c) => `✕ ${c.name}: ${c.detail}`).join('\n') +
      (endsFail ? `\n\nThe two ends read as ΔE ${endsCVD.toFixed(1)} apart under ${endsKind} — ` +
        'roughly one colour. Red→Blue reads the same way to everyone.' : '');
}

function setPalette(from, to) {
  state.filters.hue = from;
  state.filters.hueTo = to;
  $('#f-hue').value = from;
  $('#f-hue-to').value = to;
  localStorage.setItem('atlas-hue', from);
  localStorage.setItem('atlas-hue-to', to);
  renderPaletteBadge();
  render();
}

function populateHueSelects() {
  const opts = Object.entries(window.ATLAS_PALETTE.ANCHORS)
    .map(([k, a]) => `<option value="${k}">${a.label}</option>`).join('');
  $('#f-hue').innerHTML = opts;
  $('#f-hue-to').innerHTML = opts;
}

/**
 * Repos used to be keyed by GitHub slug, which collided whenever two folders
 * held clones of one repo. Keys are now paths. Adopt any orphaned slug-keyed
 * verdict onto the clone that carries that slug's history.
 */
function migrateVerdicts(verdicts, repos) {
  const live = new Set(repos.map((r) => r.key));
  const primaryBySlug = new Map();
  for (const r of repos) {
    if (r.slug && r.isPrimaryClone) primaryBySlug.set(`gh:${r.slug}`, r.key);
  }
  // hidden:true predates the visible/hidden/ignored model. Carry it over
  // rather than letting a boolean that no longer means anything drop things
  // you deliberately filed away back onto the map.
  for (const v of Object.values(verdicts)) {
    if (v.hidden !== undefined) {
      if (v.hidden && !v.visibility) v.visibility = 'hidden';
      delete v.hidden;
    }
  }

  let moved = 0;
  for (const oldKey of Object.keys(verdicts)) {
    if (live.has(oldKey)) continue;
    const newKey = primaryBySlug.get(oldKey);
    if (!newKey || verdicts[newKey]) continue;
    verdicts[newKey] = verdicts[oldKey];
    delete verdicts[oldKey];
    moved++;
  }
  if (moved) scheduleSave();
  return verdicts;
}

async function boot() {
  const saved = localStorage.getItem('atlas-theme');
  document.documentElement.dataset.theme =
    saved || (matchMedia('(prefers-color-scheme: light)').matches ? 'light' : 'dark');

  let payload;
  try {
    // A self-contained snapshot can inline its data instead of calling the API.
    // Saves are no-ops in that mode.
    payload = window.__ATLAS_DATA__;
    if (!payload) {
      const res = await fetch('/api/data');
      payload = await res.json();
      if (!res.ok) throw new Error(payload.error || res.statusText);
    }
  } catch (err) {
    $('#treemap').innerHTML =
      `<p class="empty-note">Could not load inventory.<br><br>${escapeHTML(err.message)}<br><br>` +
      `Run <code>npm run scan</code>, then reload.</p>`;
    return;
  }

  state.inventory = payload.inventory;
  state.repos = payload.inventory.repos;
  state.verdicts = migrateVerdicts(payload.verdicts || {}, state.repos);

  // Restore what you last chose to look at.
  populateHueSelects();
  restoreFocus();
  state.filters.color = localStorage.getItem('atlas-color') || state.filters.color;
  state.filters.hue = localStorage.getItem('atlas-hue') || state.filters.hue;
  state.filters.hueTo = localStorage.getItem('atlas-hue-to') || state.filters.hueTo;
  state.filters.scale = localStorage.getItem('atlas-scale') || state.filters.scale;
  $('#f-color').value = state.filters.color;
  $('#f-hue').value = state.filters.hue;
  $('#f-hue-to').value = state.filters.hueTo;
  $('#f-scale').value = state.filters.scale;
  setPinned(localStorage.getItem('atlas-pin') === '1');
  syncHueControl();

  const c = payload.inventory.counts;
  $('#scan-stamp').textContent =
    `${c.total} projects · ${num(c.openIssues)} open issues · ${c.localOnly} local-only · ` +
    `${c.remoteOnly} not cloned · ${c.duplicateClones} duplicate clones · ` +
    `scanned ${fmtAgo(payload.inventory.generatedAt)}`;
  $('#save-state').textContent = `${Object.keys(state.verdicts).length} judged`;

  wireGlobal();
  render();
}

boot();
